ALTER TABLE DONATIONS MODIFY (IS_TEACHER_ACCT ANNOTATIONS (ADD value_description 'commonsense evidence: f: false, it means this donor is not a teacher t: true, it means this donor is a teacher'));
COMMENT ON COLUMN DONATIONS.DONATION_TIMESTAMP IS 'the time of donation';
COMMENT ON COLUMN DONATIONS.DONATION_TO_PROJECT IS 'amount to project, excluding optional support (tip)';
COMMENT ON COLUMN DONATIONS.DONATION_OPTIONAL_SUPPORT IS 'amount of optional support';
COMMENT ON COLUMN DONATIONS.DONATION_TOTAL IS 'donated amount';
ALTER TABLE DONATIONS MODIFY (DONATION_TOTAL ANNOTATIONS (ADD value_description 'commonsense evidence:donated amount = donation_to_project + donation_optional_support'));
COMMENT ON COLUMN DONATIONS.DOLLAR_AMOUNT IS 'donated amount in US dollars';
