COMMENT ON COLUMN DONATIONS.PAYMENT_METHOD IS 'what card/payment option was used';
COMMENT ON COLUMN DONATIONS.PAYMENT_INCLUDED_ACCT_CREDIT IS 'whether a portion of a donation used account credits redemption';
ALTER TABLE DONATIONS MODIFY (PAYMENT_INCLUDED_ACCT_CREDIT ANNOTATIONS (ADD value_description 'commonsense evidence: f: false, a portion of a donation didn''t use account credits redemption t: true, a portion of a donation used account credits redemption'));
COMMENT ON COLUMN DONATIONS.PAYMENT_INCLUDED_CAMPAIGN_GIFT_CARD IS 'whether a portion of a donation included corporate sponsored gift card';
ALTER TABLE DONATIONS MODIFY (PAYMENT_INCLUDED_CAMPAIGN_GIFT_CARD ANNOTATIONS (ADD value_description 'commonsense evidence: f: false, a portion of a donation included corporate sponsored gift card t: true, a portion of a donation included corporate sponsored gift card'));
COMMENT ON COLUMN DONATIONS.PAYMENT_INCLUDED_WEB_PURCHASED_GIFT_CARD IS 'whether a portion of a donation included citizen purchased gift card (ex: friend buy a gift card for you)';
ALTER TABLE DONATIONS MODIFY (PAYMENT_INCLUDED_WEB_PURCHASED_GIFT_CARD ANNOTATIONS (ADD value_description ' f: false t: true'));
COMMENT ON COLUMN DONATIONS.PAYMENT_WAS_PROMO_MATCHED IS 'whether a donation was matched 1-1 with corporate funds';
ALTER TABLE DONATIONS MODIFY (PAYMENT_WAS_PROMO_MATCHED ANNOTATIONS (ADD value_description 'commonsense evidence: f: false, a donation was not matched 1-1 with corporate funds t: true, a donation was matched 1-1 with corporate funds'));
COMMENT ON COLUMN DONATIONS.VIA_GIVING_PAGE IS 'donation given via a giving / campaign page (example: Mustaches for Kids)';
COMMENT ON COLUMN DONATIONS.FOR_HONOREE IS 'donation made for an honoree';
ALTER TABLE DONATIONS MODIFY (FOR_HONOREE ANNOTATIONS (ADD value_description 'commonsense evidence: f: false, this donation is not made for an honoree t: true, this donation is made for an honoree'));
COMMENT ON COLUMN DONATIONS.DONATION_MESSAGE IS 'donation comment/message.';
